        summary: 'The importance of a strong navy became very clear after the long Battle of Terra. The losses on the surface were staggering, and could have been avoided with a',
        categories: ['Categories','Prefecture Military'],
        rawContent: `The importance of a strong navy became very clear after the long Battle of Terra. The losses on the surface were staggering, and could have been avoided with a clear naval superiority in orbit. The Prefecture Navy was placed under the direct control of Fleet Admiral Robert Marshall and ordered to go through drastic reorganization and overhaul.

In the year [[2324]], the reorganization was complete. The new Prefecture Galactic Navy is organized into a monolithic system of Fleets, installations, air commands, special forces, and space stations. Altogether, the Navy is led by the Fleet Admiral, one of the most important members of the military command. In the days of the Empire, the rank was known as the Grand Admiral, and was actually the commander-in-chief of the Empire's military.

[[Category:Prefecture Military]]`
