        title: 'Federated Districts Air Force',
        author: 'ABailey',
        lastUpdated: '2008-09-08 17:20:12',
        summary: 'The Federated Districts Air Force is responsible for most flight-related combat.',
        categories: ['Prefecture Military','Prefecture Air Force'],
